var r=[{title:`Välj ett repetitionsintervall`,text:`Välj en övning, ett antal set och ett intervall, till exempel tre set med 8–12 repetitioner. Börja med en vikt som låter dig nå botten av intervallet med stabil teknik och några repetitioner i reserv. Intervallet behöver inte vara 8–12. Ditt mål och övningen avgör gränserna.`},{title:`Förtjäna viktökningen`,text:`Gör först fler bra repetitioner med samma vikt över flera pass. När varje set når toppen av intervallet vid den ansträngning du planerade, lägg till det minsta viktsteg du har. Dina repetitioner sjunker då oftast mot den nedre änden igen, och cykeln börjar om.`},{title:`Exempel`,text:`Vecka 1: hantelrodd med 12 kg för 10, 9, 8. Vecka 2: 11, 10, 9. Vecka 3: 12, 12, 12 med stadig kontroll. Vecka 4: prova 14 kg för 9, 8, 8, om du klarar det hoppet med bra form. De här talen visar hur det kan gå. Du behöver inte förbättras varje vecka.`},{title:`När du ska anpassa regeln`,text:`Ett stort viktkliv kan vara för tungt, särskilt för små muskler eller med begränsad utrustning hemma. Stanna i så fall vid din nuvarande belastning, lägg till totala repetitioner eller välj en variant däremellan. Om ett pass känns ovanligt tröttande, upprepa det senaste målet och spara progressionen till senare. Verkliga framsteg går ofta upp och ner.`},{title:`Så använder du TrainUp`,text:`Din plan ger varje övning set och ett repetitionsmål, och under ett pass noterar du de repetitioner du slutför i varje set. TrainUp föreskriver inga vikter, så du bestämmer när du lägger till belastning. När du når toppen av intervallet i varje set, kontrollera din RPE och din teknik innan du går tyngre.`}];var n=[{label:`ACSM:s ställningstagande 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`NSCA: grunder i säkerhet och styrketräning`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`},{label:`Mayo Clinic: teknik vid styrketräning (2026)`,url:`https://www.mayoclinic.org/healthy-lifestyle/fitness/in-depth/weight-training/art-20045842`}];var a={sections:r,sources:n};export{a as default,r as sections,n as sources};